import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {TextFieldComponent} from "./textField.component";
import {PI_TEXT_FIELD_ACTION, PI_TEXT_FIELD_CARD} from "./textField.types";

export * from "./textField.types";

registerCardComponent({
  name: PI_TEXT_FIELD_CARD,
  component: TextFieldComponent,
  events: actionTypesToEvents(PI_TEXT_FIELD_ACTION),
});

import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Input} from "@/components/ui/input";
import {useFormContext} from "@/cards/form/form.context";
import type {PiTextFieldEvents, PiTextFieldProps} from "./textField.types";

export const TextFieldComponent = (
  props: PiCardProps<PiTextFieldProps, PiTextFieldEvents>,
): React.ReactNode => {
  const {
    name,
    value: propValue = "",
    type = "text",
    placeholder,
    disabled,
    cardName,
    onChanged,
  } = props;

  // `id` and `invalid` may be injected by a parent pi/field card via
  // Pihanga's extra-prop forwarding.  They are not in the official type so
  // we read them through an escape hatch.
  const injectedId = (props as {id?: string}).id;
  const invalid = Boolean((props as {invalid?: boolean}).invalid);

  // Detect if we are inside a pi/form card via React context.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  const value = useFormData
    ? ((form.formData[name!] as string | undefined) ?? "")
    : propValue;

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const newValue = e.target.value;
    if (useFormData) {
      form.handleChange(name!, newValue);
    } else {
      onChanged({name, value: newValue});
    }
  }

  // Use the id injected by pi/field (for label↔control linking); fall back
  // to a locally-generated id when used standalone.
  const selfId = `${cardName}-${name ?? "field"}`;
  const fieldId = injectedId ?? selfId;

  return (
    <Input
      id={fieldId}
      type={type}
      value={value}
      onChange={handleChange}
      placeholder={placeholder}
      disabled={disabled}
      aria-invalid={invalid || undefined}
    />
  );
};

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PI_TEXT_FIELD_CARD = "pi/text-field";

export const TextField = createCardDeclaration<
  PiTextFieldProps,
  PiTextFieldEvents
>(PI_TEXT_FIELD_CARD);

export const PI_TEXT_FIELD_ACTION = registerActions(PI_TEXT_FIELD_CARD, [
  "changed",
]);

export const onTextFieldChanged = createOnAction<PiTextFieldChangedEvent>(
  PI_TEXT_FIELD_ACTION.CHANGED,
);

/** @deprecated Use `onTextFieldChanged` instead. */
export const onPiTextFieldChanged = onTextFieldChanged;

export type PiTextFieldProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its value from form state and writes
   * back via form.handleChange.
   */
  name?: string;

  /**
   * Controlled value used in standalone mode (outside a Form).
   * Ignored when `name` is set and the component is inside a pi/form.
   */
  value?: string;

  /** HTML input type (e.g. "text", "email", "password", "number"). */
  type?: string;

  /** Placeholder text shown when the input is empty. */
  placeholder?: string;

  /** When true, the input is disabled and non-interactive. */
  disabled?: boolean;
};

export type PiTextFieldChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** New value after the change. */
  value: string;
};

export type PiTextFieldEvents = {
  onChanged: PiTextFieldChangedEvent;
};
